css:
/* ===== WORKSHOP · tune these ===== */
:root{--wbleed:36px;--tilt-left:10deg;--tilt-right:-7deg;--wpkl:4;--wpushl:3.5cqw;--wgap:32px;--wedgepad:16px;--wtop:0px;--wline:60px;--wbot:46px;--whead:40px;--wpush:3cqw;--wpk:4;--wc:#6fdcff;--ww:#e8fbff;--wa:#ffb23f;--wr:#ff4f5a;--wg:#6cf0b5;--wd:#5f8597;--wedge:rgba(111,220,255,.30);--wglass:linear-gradient(160deg,rgba(111,220,255,.10),rgba(111,220,255,.02) 60%);--wf:"Avenir Next Condensed","Avenir Next","DIN Condensed",sans-serif;--wm:Menlo,ui-monospace,SFMono-Regular,monospace;--font-sans:"Avenir Next",-apple-system,BlinkMacSystemFont,sans-serif;--wbrk:linear-gradient(#6fdcff,#6fdcff) left top/16px 2px no-repeat,linear-gradient(#6fdcff,#6fdcff) left top/2px 16px no-repeat,linear-gradient(#6fdcff,#6fdcff) right top/16px 2px no-repeat,linear-gradient(#6fdcff,#6fdcff) right top/2px 16px no-repeat,linear-gradient(#6fdcff,#6fdcff) left bottom/16px 2px no-repeat,linear-gradient(#6fdcff,#6fdcff) left bottom/2px 16px no-repeat,linear-gradient(#6fdcff,#6fdcff) right bottom/16px 2px no-repeat,linear-gradient(#6fdcff,#6fdcff) right bottom/2px 16px no-repeat;--wpane:var(--wglass),rgba(3,10,18,.6)}
@property --wang{syntax:"<angle>";inherits:false;initial-value:0deg}
@keyframes wspin{to{transform:rotate(360deg)}}
@keyframes wpulse{50%{opacity:.35}}
@keyframes wcore{to{--wang:360deg}}
@keyframes wscan{from{background-position:0 120%}to{background-position:0 -20%}}
@property --wb1{syntax:"<length>";inherits:false;initial-value:4px}
@keyframes wb1{0%,100%{--wb1:4px}50%{--wb1:16px}}
@property --wb2{syntax:"<length>";inherits:false;initial-value:4px}
@keyframes wb2{0%,100%{--wb2:4px}50%{--wb2:16px}}
@property --wb3{syntax:"<length>";inherits:false;initial-value:4px}
@keyframes wb3{0%,100%{--wb3:4px}50%{--wb3:16px}}
@property --wb4{syntax:"<length>";inherits:false;initial-value:4px}
@keyframes wb4{0%,100%{--wb4:4px}50%{--wb4:16px}}
@property --wb5{syntax:"<length>";inherits:false;initial-value:4px}
@keyframes wb5{0%,100%{--wb5:4px}50%{--wb5:16px}}
::selection{background:rgba(111,220,255,.3)}
::-webkit-scrollbar{width:8px;height:8px}
::-webkit-scrollbar-thumb{background:rgba(111,220,255,.22);border-radius:99px;border:2px solid transparent;background-clip:padding-box}
::-webkit-scrollbar-thumb:hover{background:rgba(111,220,255,.5);background-clip:padding-box}
[data-slot="scroll-area-thumb"]{background:rgba(111,220,255,.25)!important}
svg.lucide{stroke-width:1.75}
body{font-family:"Avenir Next",-apple-system,BlinkMacSystemFont,sans-serif!important}

/* ===== workshop floor + glow ===== */
html{background:radial-gradient(ellipse 36% 16% at 50% 100%,rgba(111,220,255,.28),transparent 70%) fixed,radial-gradient(ellipse 70% 60% at 50% 35%,#0a1d31,#020509 72%) fixed #020509!important}
body,#root,[data-slot="sidebar-wrapper"],[data-slot="sidebar-inset"],[data-slot="sidebar"],[data-slot="sidebar-container"],[data-chat-canvas],[data-chat-header],[data-workspace-area="composer"]{background:transparent!important}
body::before{content:"";position:fixed;left:-30%;right:-30%;bottom:0;height:46vh;z-index:30;pointer-events:none;mix-blend-mode:screen;opacity:.55;background:radial-gradient(ellipse 30% 40% at 50% 100%,rgba(111,220,255,.35),transparent 70%),linear-gradient(rgba(111,220,255,.4) 1px,transparent 1px) 0 0/64px 64px,linear-gradient(90deg,rgba(111,220,255,.4) 1px,transparent 1px) 0 0/64px 64px;transform:perspective(520px) rotateX(64deg);transform-origin:center bottom;-webkit-mask:linear-gradient(to top,#000 5%,transparent 70%);mask:linear-gradient(to top,#000 5%,transparent 70%)}

/* ===== status strip (bottom edge) ===== */
body::after{content:"T3 · WORKSHOP    ● ALL SYSTEMS NOMINAL";position:fixed;left:28px;bottom:8px;z-index:40;pointer-events:none;white-space:pre;font:600 10.5px/1 var(--wf);letter-spacing:.26em;color:var(--wg);text-shadow:0 0 10px rgba(108,240,181,.5)}
:root:has([data-chat-canvas] :is([data-timeline-row-kind="working"],[data-timeline-row-kind="work-live"])) body::after,:root:has([data-sidebar-row][aria-current="page"]:is([aria-label*=", Working"],[aria-label*=", Connecting"])) body::after{content:"T3 · WORKSHOP    ◉ PROCESSING";color:var(--wc);text-shadow:0 0 10px rgba(111,220,255,.6)}
:root:has([data-sidebar-row][aria-current="page"]:is([aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label*=", Waiting"])) body::after{content:"T3 · WORKSHOP    ◆ STANDBY · AWAITING YOUR INPUT";color:var(--wa);text-shadow:0 0 10px rgba(255,178,63,.5);animation:wpulse 1.6s ease-in-out infinite}
:root:has([data-sidebar-row][aria-current="page"]:is([aria-label*=", Failed"],[aria-label*=", Limited"])) body::after{content:"T3 · WORKSHOP    ▲ FAULT DETECTED";color:var(--wr);text-shadow:0 0 10px rgba(255,79,90,.5)}

/* ===== left pane: suit bays ===== */
[data-slot="sidebar-container"]{container-type:inline-size;border:0!important;padding:var(--wline) 0 var(--wbot) 14px!important}
[data-slot="sidebar-inner"]{position:relative;overflow:visible!important;counter-reset:wact wstb wdmg;padding-bottom:94px!important;background:transparent!important;border:0!important;box-shadow:none!important;margin-left:var(--wpushl)!important;width:calc(100% - var(--wpushl))!important;transform:perspective(calc(var(--wpkl) * 100cqw)) rotateY(var(--tilt-left));transform-origin:right center}
[data-workspace-area="conversation"]::before{content:"";position:absolute;inset:-6px;pointer-events:none;background:var(--wbrk);z-index:3}
[data-slot="sidebar-inner"]::before{content:"";position:absolute;inset:var(--wtop) 0 0 0;z-index:-1;pointer-events:none;border:1px solid var(--wedge);border-radius:6px;background:var(--wbrk),var(--wpane);box-shadow:0 0 60px rgba(111,220,255,.10),inset 0 0 40px rgba(111,220,255,.05)}
[data-slot="sidebar-content"]{counter-reset:wmk}
[data-slot="sidebar-content"]::before{content:"SUIT BAYS";display:block;flex:none;margin:6px 10px 4px;padding:0 2px 8px;border-bottom:1px solid rgba(111,220,255,.2);font:600 12.5px/1 var(--wf);letter-spacing:.3em;color:var(--wc);text-shadow:0 0 10px rgba(111,220,255,.6)}
[data-slot="sidebar-inner"]::after{content:"CORE STABLE " counter(wact) " ACTIVE " counter(wstb) " STANDBY " counter(wdmg) " DAMAGED"!important;white-space:normal!important;display:block!important;visibility:visible!important;opacity:1!important;position:absolute!important;left:10px!important;right:10px!important;bottom:8px!important;top:auto!important;width:auto!important;height:auto!important;z-index:2;pointer-events:none;box-sizing:border-box;padding:9px calc(100% - 96px - 13.5ch) 9px 76px;min-height:76px;border-top:1px solid rgba(111,220,255,.18);border-radius:4px;font:500 10.5px/1.7 var(--wm);letter-spacing:.1em;color:#8fc7da;background:radial-gradient(circle at 38px 50%,#fff 0 3px,#c5f4ff 5px,#6fdcff 9px,rgba(111,220,255,.25) 12px,transparent 14px),radial-gradient(circle at 38px 50%,transparent 0 15px,rgba(111,220,255,.85) 15px 16.5px,transparent 17px 26px,rgba(111,220,255,.4) 26px 27px,transparent 27.5px),radial-gradient(circle at 38px 50%,#06121d 0 18px,transparent 18px 24px,#06121d 24px),repeating-conic-gradient(from var(--wang) at 38px 50%,rgba(111,220,255,.85) 0 9deg,transparent 9deg 18deg),#06121d;animation:wcore 14s linear infinite}
[data-slot="sidebar-inner"]:has([data-thread-item] :is([aria-label*=", Failed"],[aria-label*=", Limited"]))::after{content:"CORE FAULT " counter(wact) " ACTIVE " counter(wstb) " STANDBY " counter(wdmg) " DAMAGED"!important}
[data-slot="sidebar-inner"] [data-slot="input-control"]{background:rgba(111,220,255,.05)!important;border:1px solid var(--wedge)!important;border-radius:3px!important;box-shadow:none!important}
[data-slot="sidebar-inner"] [data-slot="input"]{font-family:var(--wf)!important;text-transform:uppercase;letter-spacing:.18em;color:var(--wc)!important}
[data-slot="sidebar-inner"] [data-slot="input"]::placeholder{color:var(--wd)!important}
[data-testid="sidebar-working-header"] *,[data-testid="sidebar-settled-header"] *,[data-testid="sidebar-pinned-header"] *{font-family:var(--wf)!important;text-transform:uppercase;letter-spacing:.24em;color:var(--wc)!important;font-size:12px}
[data-testid="sidebar-project-folder"]>button[data-sidebar-row]>span:not([aria-hidden]){font:500 12px var(--wf)!important;text-transform:uppercase;letter-spacing:.24em;color:var(--wd)!important}
[data-slot="project-monogram"]{filter:drop-shadow(0 0 4px rgba(111,220,255,.55))}
[data-thread-item]{content-visibility:visible;counter-increment:wmk;--rc:#4aa3c2;--p:100;--lab:"READY";--anim:none}
[data-thread-item]:has(:is([aria-label*=", Done"],[aria-label*=", Completed"],[aria-label*=", Woke"])){--rc:var(--wg);--p:100;--lab:"COMPLETE"}
[data-thread-item]:has([data-sidebar-parent^="shelf:working"]),[data-thread-item]:has(:is([aria-label*=", Working"],[aria-label*=", Connecting"])){counter-increment:wmk wact;--rc:var(--wc);--p:68;--lab:"ONLINE";--anim:wspin 2.2s linear infinite}
[data-thread-item]:has(:is([aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label*=", Waiting"])){counter-increment:wmk wstb;--rc:var(--wa);--p:50;--lab:"STANDBY · NEEDS YOU";--anim:wpulse 1.2s ease-in-out infinite}
[data-thread-item]:has(:is([aria-label*=", Failed"],[aria-label*=", Limited"])){counter-increment:wmk wdmg;--rc:var(--wr);--p:14;--lab:"DAMAGED";--anim:wpulse 2s ease-in-out infinite}
[data-thread-item] [data-sidebar-row]{position:relative;height:auto!important;padding-left:46px!important;padding-bottom:17px!important;border-radius:3px!important;background:transparent!important;border:0!important;box-shadow:none!important;overflow:visible}
[data-thread-item] [data-sidebar-row]::before{content:"";position:absolute;left:9px;top:9px;width:28px;height:28px;border-radius:50%;background:conic-gradient(var(--rc) calc(var(--p) * 1%),rgba(111,220,255,.13) 0);-webkit-mask:radial-gradient(circle,transparent 10px,#000 11px);mask:radial-gradient(circle,transparent 10px,#000 11px);animation:var(--anim)}
[data-thread-item] [data-sidebar-row]::after{content:"MK " counter(wmk,decimal-leading-zero) " · " var(--lab);position:absolute;left:46px;bottom:4px;font:500 10px/1 var(--wm);letter-spacing:.08em;color:var(--rc);pointer-events:none;white-space:nowrap;text-shadow:0 0 8px color-mix(in srgb,var(--rc) 60%,transparent)}
[data-thread-item] [data-sidebar-row]:hover{background:rgba(111,220,255,.06)!important}
[data-thread-item] [data-sidebar-row][aria-current="page"]{background:linear-gradient(90deg,rgba(111,220,255,.2),rgba(111,220,255,0))!important;box-shadow:inset 2px 0 0 var(--wc)!important}
[data-thread-item]:has([data-sidebar-parent="shelf:settled"]){counter-increment:wmk;--rc:var(--wd);--anim:none}
[data-thread-item] [data-sidebar-row][data-sidebar-parent="shelf:settled"]{padding-left:34px!important;padding-bottom:0!important}
[data-thread-item] [data-sidebar-row][data-sidebar-parent="shelf:settled"]::before{width:16px;height:16px;left:9px;top:50%;margin-top:-8px;-webkit-mask:radial-gradient(circle,transparent 5px,#000 6px);mask:radial-gradient(circle,transparent 5px,#000 6px);opacity:.6}
[data-thread-item] [data-sidebar-row][data-sidebar-parent="shelf:settled"]::after{content:none}

/* ===== header ===== */
[data-chat-header]{border:0!important;height:var(--whead)!important;min-height:var(--whead)!important;box-sizing:border-box}
[data-chat-header] [data-slot="workspace-breadcrumb-text"]{font-family:var(--wf)!important;text-transform:uppercase;letter-spacing:.2em;color:var(--wd)!important;font-size:12px!important}
[data-chat-header] nav li[aria-current="page"] h2,[data-chat-header] nav li[aria-current="page"] h2 [data-slot="workspace-breadcrumb-text"]{font-family:var(--wf)!important;font-size:17px!important;font-weight:600!important;text-transform:uppercase;letter-spacing:.14em!important;color:var(--ww)!important;text-shadow:0 0 12px rgba(111,220,255,.6)}
[data-chat-header] nav li[aria-current="page"] h2 [data-slot="workspace-breadcrumb-text"]::before{content:"[ ";color:var(--wc);font-weight:400}
[data-chat-header] nav li[aria-current="page"] h2 [data-slot="workspace-breadcrumb-text"]::after{content:" ]";color:var(--wc);font-weight:400}
[data-panel-layout-controls] [data-slot="toggle"],[data-workspace-titlebar-controls] button{color:var(--wc)!important}
[data-panel-layout-controls] [data-slot="toggle"][data-pressed]{background:rgba(111,220,255,.16)!important;box-shadow:0 0 10px rgba(111,220,255,.35)}

/* ===== center pane ===== */
[data-workspace-area="conversation"]{position:relative;overflow:visible;margin:calc(var(--wline) - var(--whead)) var(--wgap) var(--wbot) var(--wgap)!important;border:1px solid var(--wedge)!important;border-radius:6px!important;background:var(--wpane)!important;box-shadow:0 0 60px rgba(111,220,255,.10),inset 0 0 40px rgba(111,220,255,.05)!important}
[data-slot="sidebar-inset"]:has([data-workspace-area="panel"]) [data-workspace-area="conversation"]{margin-right:calc(var(--wgap) - var(--wedgepad))!important}
:root:has([data-chat-column-maximized-away="true"]) [data-workspace-area="conversation"]{border-width:0!important;margin:0!important;background:none!important;box-shadow:none!important;width:0;min-width:0;overflow:hidden}
:root:has([data-chat-column-maximized-away="true"]) [data-workspace-area="conversation"]::before{content:none}
[data-user-message-bubble]{position:relative;background:rgba(111,220,255,.08)!important;border:1px solid rgba(111,220,255,.38)!important;border-radius:4px!important;box-shadow:none!important}
[data-user-message-bubble]::before{content:"YOU";position:absolute;right:12px;top:-6px;padding:0 6px;background:#04121d;font:500 9.5px/11px var(--wm);letter-spacing:.24em;color:var(--wc);pointer-events:none}
[data-message-role="assistant"] .chat-markdown{position:relative;border-left:0!important;padding-left:50px!important;background:linear-gradient(rgba(111,220,255,.35),rgba(111,220,255,.35)) 36px 0/1px 100% no-repeat}
[data-message-role="assistant"] .chat-markdown::before{content:"";position:absolute;left:2px;top:2px;width:24px;height:24px;border-radius:50%;background:radial-gradient(circle,#fff 0 14%,#bff3ff 24%,#6fdcff 44%,#0b3a52 66%);box-shadow:0 0 0 2px #03101c,0 0 0 3px rgba(111,220,255,.6),0 0 16px rgba(111,220,255,.8)}
[data-message-role="assistant"] .chat-markdown::after{content:"SYS";position:absolute;left:1px;top:34px;width:26px;padding-top:17px;text-align:center;font:600 8.5px/1 var(--wm);letter-spacing:.12em;color:var(--wc);background:linear-gradient(#6fdcff,#6fdcff) 3px 4px/2px 6px no-repeat,linear-gradient(#6fdcff,#6fdcff) 8px 1px/2px 12px no-repeat,linear-gradient(#6fdcff,#6fdcff) 13px 3px/2px 8px no-repeat,linear-gradient(#6fdcff,#6fdcff) 18px 0/2px 14px no-repeat,linear-gradient(#6fdcff,#6fdcff) 23px 5px/2px 4px no-repeat;opacity:.75;pointer-events:none}
.chat-markdown :is(h1,h2,h3,h4){font-family:var(--wf)!important;text-transform:uppercase;letter-spacing:.12em;color:var(--wc)!important;font-weight:600!important}
.chat-markdown strong{color:var(--ww)}
.chat-markdown a{color:var(--wc)!important}
.chat-markdown code[data-inline-code]{background:rgba(255,178,63,.08)!important;color:var(--wa)!important;border-radius:3px!important}
.chat-markdown th{font-family:var(--wf);text-transform:uppercase;letter-spacing:.12em;color:var(--wc)}
.chat-markdown-codeblock{position:relative;border-radius:3px!important;border:1px solid rgba(111,220,255,.18)!important;background:rgba(0,8,14,.9)!important}
.chat-markdown-codeblock::after{content:"";position:absolute;inset:-4px;pointer-events:none;background:var(--wbrk)}
[data-timeline-row-kind="work-toggle"] *,[data-timeline-row-kind="turn-fold"] *,[data-timeline-row-kind="work"] *{font-family:var(--wm)!important;letter-spacing:.02em;color:var(--wd)}
[data-timeline-row-kind="work-toggle"]>*:first-child::before,[data-timeline-row-kind="turn-fold"]>*:first-child::before{content:"◉ PROCESS LOG ›";color:var(--wc);margin-right:8px;font:500 11px var(--wm);letter-spacing:.06em;white-space:nowrap}
[data-timeline-row-kind="work-live"] *,[data-timeline-row-kind="working"] *{font-family:var(--wm)!important;color:var(--wc)}
[data-timeline-row-kind="work-live"]>*:first-child::before,[data-timeline-row-kind="working"]>*:first-child::before{content:"";--wb1:6px;--wb2:12px;--wb3:8px;--wb4:14px;--wb5:5px;display:inline-block;flex:none;width:22px;height:18px;margin-right:10px;vertical-align:middle;background:linear-gradient(transparent calc(50% - var(--wb1) / 2),#6fdcff 0 calc(50% + var(--wb1) / 2),transparent 0) 0 0/2px 100% no-repeat,linear-gradient(transparent calc(50% - var(--wb2) / 2),#6fdcff 0 calc(50% + var(--wb2) / 2),transparent 0) 5px 0/2px 100% no-repeat,linear-gradient(transparent calc(50% - var(--wb3) / 2),#6fdcff 0 calc(50% + var(--wb3) / 2),transparent 0) 10px 0/2px 100% no-repeat,linear-gradient(transparent calc(50% - var(--wb4) / 2),#6fdcff 0 calc(50% + var(--wb4) / 2),transparent 0) 15px 0/2px 100% no-repeat,linear-gradient(transparent calc(50% - var(--wb5) / 2),#6fdcff 0 calc(50% + var(--wb5) / 2),transparent 0) 20px 0/2px 100% no-repeat;animation:wb1 1s ease-in-out infinite,wb2 1s ease-in-out .15s infinite,wb3 1s ease-in-out .3s infinite,wb4 1s ease-in-out .45s infinite,wb5 1s ease-in-out .6s infinite;filter:drop-shadow(0 0 4px #6fdcff)}

/* ===== composer: voice bar ===== */
[data-slot="composer-host"],[data-chat-composer-surface]{border-radius:28px!important}
[data-slot="composer-host"]{border:1px solid rgba(111,220,255,.45)!important;background:rgba(4,16,26,.85)!important;box-shadow:0 0 34px rgba(111,220,255,.16)!important}
[data-chat-composer-surface]{background:transparent!important;border:0!important}
[data-slot="composer-host"]::before,[data-slot="composer-host"]::after,[data-chat-composer-main-surface],[data-chat-composer-main-surface]::after{border-radius:28px!important}
[data-slot="composer-host"]::before{background:rgba(4,16,26,.85)!important;backdrop-filter:none!important}
[data-slot="composer-host"]::after{border-color:transparent!important;box-shadow:none!important}
[data-chat-composer-body]{padding-left:48px!important}
.composer-tiptap{margin-left:-34px!important;padding-left:34px!important;--wbc:rgba(111,220,255,.5);--wb1:6px;--wb2:12px;--wb3:8px;--wb4:14px;--wb5:5px;background:linear-gradient(transparent calc(50% - var(--wb1) / 2),var(--wbc) 0 calc(50% + var(--wb1) / 2),transparent 0) -28px calc(.5lh - 10px)/2px 20px no-repeat content-box border-box,linear-gradient(transparent calc(50% - var(--wb2) / 2),var(--wbc) 0 calc(50% + var(--wb2) / 2),transparent 0) -23px calc(.5lh - 10px)/2px 20px no-repeat content-box border-box,linear-gradient(transparent calc(50% - var(--wb3) / 2),var(--wbc) 0 calc(50% + var(--wb3) / 2),transparent 0) -18px calc(.5lh - 10px)/2px 20px no-repeat content-box border-box,linear-gradient(transparent calc(50% - var(--wb4) / 2),var(--wbc) 0 calc(50% + var(--wb4) / 2),transparent 0) -13px calc(.5lh - 10px)/2px 20px no-repeat content-box border-box,linear-gradient(transparent calc(50% - var(--wb5) / 2),var(--wbc) 0 calc(50% + var(--wb5) / 2),transparent 0) -8px calc(.5lh - 10px)/2px 20px no-repeat content-box border-box!important}
:root:has([data-chat-canvas] :is([data-timeline-row-kind="working"],[data-timeline-row-kind="work-live"])) .composer-tiptap{--wbc:#6fdcff;animation:wb1 1s ease-in-out infinite,wb2 1s ease-in-out .15s infinite,wb3 1s ease-in-out .3s infinite,wb4 1s ease-in-out .45s infinite,wb5 1s ease-in-out .6s infinite}
[data-chat-composer-form] [data-placeholder]:not(.composer-tiptap):not(.ProseMirror){translate:34px 0}
.composer-tiptap p.is-editor-empty:first-child::before,.composer-tiptap [data-placeholder]::before{color:#8fbccf!important}
[data-chat-provider-model-picker]{border:1px solid rgba(111,220,255,.35)!important;border-radius:999px!important;background:rgba(111,220,255,.05)!important}
[data-chat-provider-model-picker]::before{content:"◉";margin-right:6px;color:var(--wc);font-size:9px}
[data-chat-provider-model-picker],[data-chat-provider-model-picker] *{font-family:var(--wm)!important;text-transform:uppercase;letter-spacing:.08em;font-size:11px;color:var(--wc)}
[data-chat-composer-form] [data-slot="select-trigger"]{border:1px solid rgba(111,220,255,.35)!important;border-radius:999px!important;background:rgba(111,220,255,.05)!important}
[data-chat-composer-form] [data-slot="select-trigger"],[data-chat-composer-form] [data-slot="select-trigger"] *{font-family:var(--wm)!important;text-transform:uppercase;letter-spacing:.08em;font-size:11px!important;color:var(--wc)!important}
[data-chat-composer-form] button[type="submit"]{border-radius:50%!important;background:radial-gradient(circle,#fff 0 12%,#c5f4ff 22%,#6fdcff 42%,#0b3a52 72%)!important;box-shadow:0 0 0 2px #03101c,0 0 0 3px rgba(111,220,255,.7),0 0 18px rgba(111,220,255,.8)!important;color:#01131d!important}
[data-chat-composer-form] button[type="submit"] svg,[data-chat-composer-form] button[type="submit"] svg *{color:#01131d!important;stroke-width:2.4}
[data-chat-composer-form] button[type="submit"]:disabled{filter:saturate(.4) brightness(.6)}
[data-chat-composer-form] button[type="submit"]:not(:has(svg)):not(#w){border-radius:999px!important;background:rgba(111,220,255,.15)!important;color:var(--wc)!important;box-shadow:0 0 0 1px rgba(111,220,255,.6),0 0 14px rgba(111,220,255,.35)!important;font-family:var(--wf)!important;text-transform:uppercase;letter-spacing:.14em}
button:is([aria-label="Stop generation"],[aria-label="Stopping"]):not(#w){border-radius:50%!important;background:radial-gradient(circle,#fff 0 10%,#ffc2c6 20%,#ff4f5a 44%,#4a0a10 72%)!important;box-shadow:0 0 0 2px #03101c,0 0 0 3px rgba(255,79,90,.7),0 0 18px rgba(255,79,90,.8)!important}
button:is([aria-label="Stop generation"],[aria-label="Stopping"]):not(#w) svg,button:is([aria-label="Stop generation"],[aria-label="Stopping"]):not(#w) svg *{color:#1a0306!important;fill:#1a0306!important}

/* ===== right pane: hologram ===== */
[data-workspace-area="panel"]{position:relative;container-type:inline-size;background:transparent!important;border:0!important;padding:0 16px calc(var(--wbot) - var(--wbleed)) 0!important}
[data-workspace-area="panel"]::after{content:"";position:absolute;left:20%;right:24%;bottom:calc(var(--wbot) + 1px);height:28px;pointer-events:none;z-index:7;background:linear-gradient(to top,rgba(111,220,255,.55),rgba(111,220,255,0));clip-path:polygon(44% 100%,56% 100%,100% 0,0 0)}
[data-right-panel-tabbar]{background:transparent!important;border:0!important;padding-left:12px!important;margin-left:8px!important;overflow:visible!important;height:var(--whead)!important;min-height:var(--whead)!important;box-sizing:border-box}
[data-right-panel-tab-list]{padding-left:6px!important;padding-right:6px!important;scroll-padding-left:6px;overflow-y:visible}
[data-right-panel-tab-list] [data-active-tab]{border-radius:3px!important;background:rgba(111,220,255,.05)!important;border:1px solid rgba(111,220,255,.2)!important}
[data-right-panel-tab-list] [data-active-tab] *{font-family:var(--wf)!important;text-transform:uppercase;letter-spacing:.14em}
[data-right-panel-tab-list] [data-active-tab="true"]{background:rgba(111,220,255,.16)!important;border-color:var(--wc)!important;box-shadow:0 0 12px rgba(111,220,255,.35)}
[data-right-panel-tab-list] [data-active-tab="true"] *{color:var(--wc)!important}
[data-right-panel-surface-content]{position:relative;overflow:visible!important;border:1px solid var(--wedge)!important;border-radius:6px!important;background:var(--wbrk),var(--wpane)!important;box-shadow:0 0 14px rgba(111,220,255,.14),inset 0 0 40px rgba(111,220,255,.05)!important;padding:14px 14px 30px!important;margin-top:calc(var(--wline) - var(--whead))!important;margin-left:var(--wedgepad)!important;margin-right:var(--wpush)!important;margin-bottom:var(--wbleed)!important;transform:perspective(calc(var(--wpk) * 100cqw)) rotateY(var(--tilt-right));transform-origin:left center}
[data-right-panel-surface-content]>*{border-radius:3px!important;overflow:hidden;box-shadow:0 0 0 1px rgba(111,220,255,.45),0 0 34px rgba(111,220,255,.28)}
[data-right-panel-surface-content]::before{content:"HOLO FEED · LIVE";position:absolute;top:-8px;left:18px;padding:0 8px;background:#03101a;font:600 10.5px/15px var(--wf);letter-spacing:.24em;color:var(--wc);z-index:6;pointer-events:none}
[data-right-panel-surface-content]::after{content:"";position:absolute;inset:14px 14px 30px;z-index:5;pointer-events:none;border-radius:3px;background:linear-gradient(transparent 0 44%,rgba(111,220,255,.08) 50%,transparent 56%) 0 0/100% 300% no-repeat;animation:wscan 6s linear infinite}
[data-right-panel-surface-content] [data-slot="input-control"]{background:rgba(111,220,255,.05)!important;border:1px solid rgba(111,220,255,.25)!important;border-radius:3px!important;box-shadow:none!important}
[data-right-panel-surface-content] input{font-family:var(--wm)!important;font-size:11.5px!important;letter-spacing:.02em;color:var(--wc)!important}
:root:has([data-chat-column-maximized-away="true"]) [data-workspace-area="panel"]{padding-left:var(--wgap)!important}
:root:has([data-chat-column-maximized-away="true"]) [data-right-panel-surface-content]{transform:none!important;margin-right:0!important}
[data-workspace-area="panel"]:has([data-browser-surface-slot]) [data-right-panel-surface-content]{transform:none!important;margin-right:0!important}
[data-workspace-area="panel"]:has([data-browser-surface-slot]) [data-right-panel-surface-content]::after{content:none}

/* ===== popups, terminal, details ===== */
[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="dialog-popup"]{background:rgba(4,14,24,.97)!important;border:1px solid rgba(111,220,255,.35)!important;border-radius:5px!important;box-shadow:0 0 40px rgba(111,220,255,.15),0 20px 50px #000a!important}
[data-slot="tooltip-popup"]{background:rgba(4,14,24,.97)!important;border:1px solid rgba(111,220,255,.4)!important;border-radius:3px!important;color:var(--ww)!important;font-family:var(--wm)!important;font-size:11px!important;letter-spacing:.04em}
[data-slot="switch"][data-checked],[data-slot="switch"][aria-checked="true"]{background:var(--wc)!important;box-shadow:0 0 10px rgba(111,220,255,.5)}
[data-thread-terminal-drawer]{border-top:1px solid var(--wc)!important;box-shadow:0 -10px 30px rgba(111,220,255,.12)}
[data-thread-details-card]{background:var(--wpane)!important;border:1px solid var(--wedge)!important;border-radius:6px!important;box-shadow:0 0 40px rgba(111,220,255,.12)!important}
